SELECT AVG(CAST(metric_0001 AS DOUBLE PRECISION)) AS avg_metric_0001, AVG(CAST(metric_1250 AS DOUBLE PRECISION)) AS avg_metric_1250, AVG(CAST(metric_2500 AS DOUBLE PRECISION)) AS avg_metric_2500, AVG(CAST(metric_3750 AS DOUBLE PRECISION)) AS avg_metric_3750, AVG(CAST(metric_5000 AS DOUBLE PRECISION)) AS avg_metric_5000 FROM wide5000 PREWHERE time >= '2024-09-23' AND time < '2025-01-01'
